WITH localized_ci AS MATERIALIZED (SELECT ci_id,ci_key,kind,CASE WHEN name LIKE 'Стойка %' THEN 'Rack '||substr(name,8) ELSE CASE name WHEN 'Автоматизированная банковская система' THEN 'Core Banking' WHEN 'Дистанционное банковское обслуживание' THEN 'Digital Banking' WHEN 'Кадровая система' THEN 'Human Resources' WHEN 'Мониторинг инфраструктуры' THEN 'Infrastructure Monitoring' WHEN 'Управление отношениями с клиентами' THEN 'Customer Relationship Management' WHEN 'Хранилище данных' THEN 'Data Warehouse' WHEN 'ЦОД «Север»' THEN 'DC North' WHEN 'ЦОД «Восток»' THEN 'DC East' WHEN 'ЦОД «Резерв»' THEN 'DC Reserve' WHEN 'Зал A · Север' THEN 'Hall A · North' WHEN 'Зал A · Восток' THEN 'Hall A · East' WHEN 'Зал A · Резерв' THEN 'Hall A · Reserve' WHEN 'Зал B · Север' THEN 'Hall B · North' WHEN 'Зал B · Восток' THEN 'Hall B · East' WHEN 'Зал B · Резерв' THEN 'Hall B · Reserve' ELSE name END END AS name,owner_team_id,lifecycle,retired_at,first_seen_at,last_seen_at FROM dcmon.ci)
SELECT 0::bigint id,'All DCs'::text label UNION ALL
        SELECT s.ci_id,c.name FROM dcmon.site s JOIN localized_ci c ON c.ci_id=s.ci_id ORDER BY id;
